122: // adapted bool for one package, with disk cache (null results are not cached).
123: async function isAdapted(ecoCanon, name, refresh = false) {
124:   const eco = String(ecoCanon || '').toLowerCase();
125:   const cfg = HARMONY_MIRRORS[eco];
126:   if (!cfg) return false;
127:   const c = loadCache();
128:   const key = `${eco}:${normalize(name)}`;
129:   const hit = c[key];
130:   if (!refresh && hit && Date.now() - (hit.ts || 0) < CACHE_TTL_MS) return hit.adapted;
131:   let res;
132:   if (cfg.kind === 'list') {
133:     const set = await adaptedList(cfg, refresh);
134:     res = set === null ? null : nameVariants(name).some((v) => set.has(v));
135:   } else {
136:     res = await probe(cfg, name);
137:   }
138:   if (res === null) return hit ? hit.adapted : false;   // keep stale on transient error
139:   c[key] = { adapted: res, ts: Date.now() };
140:   saveCache();
141:   return res;
142: }
