155: // { ecosystem, source, results: {name:{adapted,source}}, adaptedCount, total }
156: async function statusFor(ecoCanon, names, refresh = false) {
157:   const eco = String(ecoCanon || '').toLowerCase();
158:   const src = MIRROR_LABEL[eco] || null;
159:   const flags = await _mapLimited(names, (nm) => isAdapted(eco, nm, refresh));
160:   const results = {};
161:   let adaptedCount = 0;
162:   names.forEach((nm, k) => {
163:     const hit = !!flags[k];
164:     if (hit) adaptedCount++;
165:     results[nm] = { adapted: hit, source: hit ? src : null };
166:   });
167:   return { ecosystem: eco, source: src, results, adaptedCount, total: names.length };
168: }
